def _build_component_06():
    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            rank = (event.get("revision", 0), position)
            if event_id not in winners or rank > winners[event_id][0]:
                winners[event_id] = (rank, event)
        balances = dict(data.get("opening", {}))

        def rounded(num, den, mode):
            if mode == "half_up":
                return (2 * num + den) // (2 * den)
            return num // den

        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, data["rounding"])
            tax = rounded(net * event.get("tax_bp", 0), 10000, data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        installed = {}
        edges = {}
        best_vector = None
        best_result = None
        names = sorted(packages)

        def search(constraints, selected, graph):
            nonlocal best_vector, best_result
            # Validate/propagate constraints for all selected packages; adding
            # a new constraint can require reconsidering a prior selection.
            for name, version in selected.items():
                limits = constraints.get(name, [])
                if any(not lo <= version <= hi for lo, hi in limits):
                    return
                row = next(r for r in packages[name] if r["version"] == version)
                active = [d for d in row.get("deps", [])
                          if not d.get("feature") or d["feature"] in features]
                for dep in active:
                    depname = dep["name"]
                    limits2 = constraints.get(depname, [])
                    bound = (dep["min"], dep["max"])
                    if bound not in limits2:
                        # Avoid mutating branch data.
                        new_constraints = {k: list(v) for k, v in constraints.items()}
                        new_constraints.setdefault(depname, []).append(bound)
                        new_graph = {k: list(v) for k, v in graph.items()}
                        new_graph.setdefault(name, [])
                        if depname not in new_graph[name]:
                            new_graph[name].append(depname)
                        search(new_constraints, dict(selected), new_graph)
                        return
            unresolved = [name for name in constraints if name not in selected]
            if unresolved:
                name = min(unresolved)
                allowed = []
                for row in packages.get(name, []):
                    version = row["version"]
                    if version in blocked.get(name, []):
                        continue
                    if name in pins and version != pins[name]:
                        continue
                    if all(lo <= version <= hi for lo, hi in constraints[name]):
                        allowed.append(version)
                # Ascending choice, with full backtracking. Lexicographic
                # objective is evaluated across the complete package universe.
                for version in sorted(allowed):
                    chosen = dict(selected)
                    chosen[name] = version
                    search({k: list(v) for k, v in constraints.items()}, chosen,
                           {k: list(v) for k, v in graph.items()})
                return
            # At closure completion verify cycles and objective.
            color = {}
            def visit(n):
                if color.get(n) == 1:
                    return False
                if color.get(n) == 2:
                    return True
                color[n] = 1
                for dep in graph.get(n, []):
                    if dep in selected and not visit(dep):
                        return False
                color[n] = 2
                return True
            if not all(visit(n) for n in selected):
                return
            vector = tuple(selected.get(n, -1) for n in names)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best_result = dict(selected)

        initial = {name: [(bounds[0], bounds[1])] for name, bounds in roots.items()}
        search(initial, {}, {})
        if best_result is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_result}
    return solve


def _build_component_08():
    def solve(data):
        jobs = [j for j in data["jobs"] if j["id"] not in data.get("blocked", [])]
        k = data["k"]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        if not mandatory.issubset({j["id"] for j in jobs}):
            return {"error": "impossible"}
        best_value = None
        best_ids = None
        for chosen in combinations(jobs, k):
            ids = [j["id"] for j in chosen]
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in chosen:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            valid = True
            for group, (low, high) in quotas.items():
                count = counts.get(group, 0)
                if not low <= count <= high:
                    valid = False
                    break
            if not valid:
                continue
            ordered = sorted(chosen, key=lambda j: (j["start"], j["end"], j["id"]))
            if any(ordered[i]["end"] > ordered[i + 1]["start"] for i in range(len(ordered) - 1)):
                continue
            id_list = sorted(ids)
            value = sum(j["value"] for j in chosen)
            if best_value is None or value > best_value or (value == best_value and id_list > best_ids):
                best_value, best_ids = value, id_list
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


